<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;class Exam extends Model{protected $fillable=['school_id','term_id','school_class_id','stream_id','name','status','published_at','published_by'];protected $casts=['published_at'=>'datetime'];public function term():BelongsTo{return $this->belongsTo(Term::class);}public function schoolClass():BelongsTo{return $this->belongsTo(SchoolClass::class);}public function papers():HasMany{return $this->hasMany(ExamPaper::class);}public function publisher():BelongsTo{return $this->belongsTo(User::class,'published_by');}public function isPublished():bool{return $this->published_at!==null;}}
